import {sharedCases,makeSharedSource} from './shared-side-content.mjs';
import {newSharedWork,sharedResult,sharedSheetsView,keepSharedSheet,sharedDisplayPairs} from './shared-side-core.mjs';
import {recordGivenMath} from './given-math.mjs';
import {stopSpeech} from './play-media.mjs';

const visits=new WeakMap(),clone=x=>structuredClone(x),ownerOK=x=>typeof x==='string'&&x.trim().length>0;
const bytes=x=>{try{return JSON.stringify(x);}catch{return null;}};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(a,t)=>`<button type="button" ${a}>${esc(t)}</button>`;
const refused='This calculation could not be shown safely yet. Your choices and requested view are still here. Retry this view or download Notes.';
const target=s=>`${s.A}x + ${s.B}`;
const proposal=w=>`${w.k??'□'}(${w.a??'□'}x + ${w.b??'□'})`;
const complete=w=>['k','a','b'].every(k=>w[k]!==null);
const viewOf=a=>({work:a.work,view:a.view,step:a.step,contrasts:a.contrasts,reference:a.reference});
const displayed=a=>a.pending??viewOf(a);
const current=v=>v.screen==='sheet'?v.cards.get(v.card):v.screen==='draft'?v.drafts.get(v.key):null;
function visit(book,owner,create=true){
 let m=visits.get(book);if(!m&&create){m=new Map();visits.set(book,m);}
 let v=m?.get(owner);if(!v&&create){v={active:false,screen:'draft',key:null,card:null,serial:0,drafts:new Map(),cards:new Map(),byCase:new Map(),page:0,bound:null};m.set(owner,v);}return v;
}
function add(v,source,work){const a={source:clone(source),work:clone(work??newSharedWork(source)),view:'build',step:1,contrasts:false,reference:false,pending:null,status:''};const key=`draft-${++v.serial}`;a.ordinal=v.serial;v.drafts.set(key,a);v.key=key;v.screen='draft';v.card=null;return a;}
export const sharedSideActive=(book,owner)=>ownerOK(owner)&&visit(book,owner,false)?.active===true;
export function openSharedSide(book,owner){if(!book||typeof book!=='object'||!ownerOK(owner))return false;const v=visit(book,owner);v.active=true;if(v.screen==='draft'&&!current(v)){const a=add(v,makeSharedSource(sharedCases[0].id));v.byCase.set(a.source.id,v.key);}return true;}
export const sharedSideEntry=()=>`<aside class="sf-entry">${button('data-equality-shared-side','Shared Side')}<span>Factor an expression: turn two area terms into one rectangle.</span></aside>`;
function visible(n){if(!n?.isConnected||!n.getClientRects().length)return false;for(let p=n;p;p=p.parentElement){const c=getComputedStyle(p);if(p.hidden||p.getAttribute?.('aria-hidden')==='true'||c.display==='none'||['hidden','collapse'].includes(c.visibility))return false;if(p.tagName==='DETAILS'&&!p.open&&p!==n&&!p.querySelector(':scope>summary')?.contains(n))return false;}return true;}
export function bindSharedEntry(book,ctx){const n=document.querySelector('[data-equality-shared-side]'),owner=ctx.explorerId?.();if(!n||!ownerOK(owner))return;const chain=[];for(let p=n;p;p=p.parentElement)chain.push([p,p.parentNode]);n.addEventListener('click',()=>{if(!visible(n)||n.disabled||location.hash!=='#learn/math/equality'||ctx.notebook?.()!==book||ctx.explorerId?.()!==owner||ctx.isActive?.()!==true||chain.some(([p,q])=>p.parentNode!==q))return;if(ctx.canEnter?.()!==true){ctx.refuse?.();return;}if(openSharedSide(book,owner)){stopSpeech();ctx.render?.();document.querySelector('#sf-heading')?.focus();}});}
const adopt=(a,r)=>{a.work=r.work;a.view=r.view;a.step=r.step;a.contrasts=r.contrasts;a.reference=r.reference;a.pending=null;};
function syncSheet(book,v){if(v.screen!=='sheet')return;const row=sharedSheetsView(book).items.find(i=>i.readable&&i.id===v.card);if(!row){v.screen='shelf';v.card=null;return;}const a=v.cards.get(v.card);if(!a||a.rawBytes!==bytes(row.raw)){const s={source:clone(row.raw.source),work:clone(row.raw.work),view:'build',step:1,contrasts:false,reference:false,pending:null,status:'',raw:row.raw,rawBytes:bytes(row.raw)};v.cards.set(v.card,s);}else a.raw=row.raw;}
function qualify(book,a,r,ctx){return recordGivenMath(book,sharedDisplayPairs(a.source,r.work,r),ctx);}
export function prepareSharedDisplay(book,owner,ctx={}){
 const v=ownerOK(owner)?visit(book,owner,false):null;if(!v?.active)return {ok:true,changed:false};syncSheet(book,v);const a=current(v);if(!a)return {ok:true,changed:false};if(a.pending)return {ok:false,changed:false};const r=viewOf(a),ok=ctx.notebook?.()===book&&ctx.explorerId?.()===owner&&ctx.isActive?.()===true;const result=ok?qualify(book,a,r,ctx):{ok:false,changed:false};if(!result.ok){a.pending=clone(r);a.status=refused;}return result;
}
function field(w,k,label,ro){const missing=w[k]===null;return `<fieldset class="sf-number"><legend>${esc(label)}</legend><output data-sf-value="${k}">${missing?'Not chosen':w[k]}</output><div>${button(`data-sf-adjust="${k}" data-sf-delta="-1" aria-label="Decrease ${esc(label)} by 1"${ro||missing||w[k]===(k==='k'?1:0)?' disabled':''}`,'−')}${button(`data-sf-choose="${k}"${ro?' disabled':''}`,'Choose')}${button(`data-sf-adjust="${k}" data-sf-delta="1" aria-label="Increase ${esc(label)} by 1"${ro||missing||w[k]===24?' disabled':''}`,'+')}${button(`data-sf-clear="${k}"${ro||missing?' disabled':''}`,'Clear')}</div></fieldset>`;}
function areaTable(w){const X=w.a*w.x,width=X+w.b;return `<div class="sf-table-wrap"><table><caption>Proposed rectangle</caption><thead><tr><th>Part</th><th aria-label="Dimensions in centimeters"><span class="sf-wide">Dimensions in centimeters</span><span class="sf-compact">Sides (cm)</span></th><th aria-label="Area in square centimeters"><span class="sf-wide">Area in square centimeters</span><span class="sf-compact">Area (cm²)</span></th></tr></thead><tbody><tr><th>x-region</th><td>${w.k} by ${X}</td><td>${w.k*X}</td></tr><tr><th>Number region</th><td>${w.k} by ${w.b}</td><td>${w.k*w.b}</td></tr><tr><th>Whole proposed rectangle</th><td>${w.k} by ${width}</td><td>${w.k*width}</td></tr></tbody></table></div>`;}
function geometry(w){
 if(!complete(w))return '';
 const X=w.a*w.x,B=w.b,width=X+B,K=w.k;
 if(!width)return '<p>Both inside terms are zero, so this proposal has zero area. No positive-width rectangle is drawn.</p>';
 const W=600,H=230,pad=22,scale=Math.min((W-2*pad)/width,(H-2*pad)/K),rw=width*scale,rh=K*scale,left=(W-rw)/2,top=(H-rh)/2;
 const description=`Proposed rectangle: outside side ${K} centimeters, inside side ${width} centimeters. It splits into widths ${X} and ${B}. Areas are ${K*X} and ${K*B} square centimeters. Total area is ${K*width} square centimeters. Exact dimensions and areas are repeated in the table.`;
 return `<figure class="sf-picture"><svg data-sf-rectangle viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(description)}"><g data-sf-whole>${X?`<rect class="sf-x-region" x="${left}" y="${top}" width="${X*scale}" height="${rh}"/>`:''}${B?`<rect class="sf-number-region" x="${left+X*scale}" y="${top}" width="${B*scale}" height="${rh}"/>`:''}</g></svg><figcaption>Outside side: ${K} cm. Inside side: ${w.a} times ${w.x} plus ${B} = ${width} cm.</figcaption><p data-sf-thin hidden>Very thin drawing — use the dimensions and area table.</p></figure>${areaTable(w)}${!X||!B?`<p>The ${!X?'x-region':'number region'} has zero area. It has no width in the drawing.</p>`:''}`;
}
const model=(s,w)=>`<p>At x = ${w.x}, ${s.A} times ${w.x} is ${s.A*w.x}; plus ${s.B} gives ${s.A*w.x+s.B} square centimeters.</p>${geometry(w)}`;
function compare(s,w){
 if(!complete(w))return `<p>Still to choose: ${['k','a','b'].filter(k=>w[k]===null).map(k=>({k:'Outside factor k',a:'Inside x count a',b:'Inside number b'}[k])).join(', ')}. Choose each missing term before comparing the product. You can keep an unfinished sheet.</p>`;
 const r=sharedResult(s,w);
 return `<section class="sf-comparison" data-sf-computed><h2>Expand both terms</h2><p class="sf-equation">${esc(proposal(w))} = ${r.expanded[0]}x + ${r.expanded[1]}</p><p>${r.formFit?'Both coefficients match. The product expands to the target expression.':'These coefficient pairs differ. Try changing a term, or keep this idea to look at later.'}</p><p>At x = ${w.x}, ${s.A} times ${w.x} is ${s.A*w.x}; plus ${s.B} gives ${s.A*w.x+s.B} square centimeters.</p><p>At x = ${w.x}, ${w.a} times ${w.x} is ${w.a*w.x}; plus ${w.b} gives width ${w.a*w.x+w.b} centimeters. ${w.k} times ${w.a*w.x+w.b} gives ${w.k*(w.a*w.x+w.b)} square centimeters.</p><p>${r.valueFit?'The numerical areas match at this x. Check the coefficients before calling the expressions identical.':'The numerical areas differ at this x.'}</p>${areaTable(w)}</section>`;
}
function reference(s,w){const g=sharedResult(s,w).gcd;return `<section class="sf-reference" data-sf-computed><h2>A shared-side reference</h2><p>${esc(s.referenceIntro)}</p><p>${g===1?`Only 1 is a positive integer common factor of these two coefficients. Factoring out 1 leaves the expression unchanged. Check both: 1 times ${s.A} is ${s.A}; 1 times ${s.B} is ${s.B}.`:`The greatest positive integer common factor is ${g}. Dividing both coefficients gives ${s.A/g}x + ${s.B/g}. Check both: ${g} times ${s.A/g} is ${s.A}; ${g} times ${s.B/g} is ${s.B}. Expanding returns ${s.A}x + ${s.B}.`}</p><p class="sf-equation">${target(s)} = ${g}(${s.A/g}x + ${s.B/g})</p>${complete(w)&&w.k*w.a===s.A&&w.k*w.b===s.B&&w.k<g?'<p>This product matches. Its outside factor is a common factor; a greater positive integer common factor also exists.</p>':''}</section>`;}
function shelf(book,v){const vs=sharedSheetsView(book),pages=Math.max(1,Math.ceil(vs.items.length/8));v.page=Math.min(v.page,pages-1);return `<h2>Kept sheets</h2>${vs.status==='unavailable'?'<p>Earlier Shared Side work is retained. This version cannot add a sheet to that format. Download Notes or use another activity.</p>':''}${vs.items.slice(v.page*8,v.page*8+8).map(r=>r.readable?`<article><h3>${esc(r.raw.source.title)}</h3><p>${esc(target(r.raw.source))} · ${esc(proposal(r.raw.work))}</p>${button(`data-sf-sheet="${esc(r.id)}"`,'Open this sheet')}</article>`:'<p>This earlier sheet is retained in Notes and cannot be edited here. Other readable sheets stay open.</p>').join('')||'<p>No sheets kept yet. Choose a proposal, then Keep this sheet.</p>'}<p>Page ${v.page+1} of ${pages}</p>${button(`data-sf-page="-1"${v.page===0?' disabled':''}`,'Previous shelf page')}${button(`data-sf-page="1"${v.page===pages-1?' disabled':''}`,'Next shelf page')}`;}
export function sharedSidePage(book,owner){
 const v=visit(book,owner,false);if(!v?.active)return '';const a=current(v),r=a?displayed(a):null,s=a?.source,w=r?.work,ro=v.screen==='sheet',blocked=!!a?.pending;
 const activeView=v.screen==='shelf'?'shelf':r?.view;
 return `<section class="sf-page" data-sf-root><header><button type="button" data-sf-back>Return to Equality Desk</button><h1 id="sf-heading" tabindex="-1">Find a shared side.</h1></header><nav class="sf-tabs" aria-label="Shared Side turns">${['build','compare','learn','shelf'].map(k=>button(`data-sf-view="${k}" aria-current="${activeView===k?'step':'false'}"`,{build:'Build',compare:'Compare',learn:'Learn',shelf:'Kept sheets'}[k])).join('')}</nav><div class="sf-selectors"><label>Choose a job<select data-sf-case>${s&&!sharedCases.some(c=>c.id===s.id)?'<option value="" selected>Earlier saved source</option>':''}${sharedCases.map(c=>`<option value="${esc(c.id)}"${s?.id===c.id?' selected':''}>${esc(c.title)}</option>`).join('')}</select></label><label>Choose a working draft<select data-sf-draft>${v.screen!=='draft'?'<option value="" selected>Choose a working draft</option>':''}${[...v.drafts].map(([id,d])=>`<option value="${id}"${v.screen==='draft'&&id===v.key?' selected':''}>${esc(d.source.title)} · draft ${d.ordinal}</option>`).join('')}</select></label></div>${v.screen==='shelf'?shelf(book,v):a?`<div class="sf-summary"><h2>${esc(s.title)}</h2><p>${esc(s.request)}</p><div class="sf-expression"><strong>${esc(target(s))}</strong><span>your proposal</span><strong data-sf-proposal>${esc(proposal(w))}</strong></div><p data-sf-summary-x>Your proposal’s x: ${w.x}</p></div>${ro?`<p>This kept sheet stays unchanged. Help shown now stays in this visit; Copy to Build carries that support into a new draft.</p>${button('data-sf-copy','Copy to Build')}`:''}${blocked?`<p class="sf-notice" data-sf-blocked>${refused}</p>${button('data-sf-retry','Retry this view')}`:''}${r.view==='build'?`<div class="sf-workbench"><div class="sf-edit"><div class="sf-controls">${field(w,'k','Outside factor k',ro)}${field(w,'a','Inside x count a',ro)}${field(w,'b','Inside number b',ro)}</div><div class="sf-x-control"><label>Change x<select data-sf-x${ro?' disabled':''}>${Array.from({length:12},(_,i)=>`<option value="${i+1}"${w.x===i+1?' selected':''}>${i+1}</option>`).join('')}</select></label>${button(`data-sf-x-one${ro?' disabled':''}`,'Set x to 1')}</div><details class="sf-notation"><summary>What do these letters mean?</summary><p>${esc(s.notation)}</p></details></div><div class="sf-model">${blocked?'':complete(w)?`<div data-sf-computed>${model(s,w)}</div>`:'<p>Choose each missing term before drawing the complete proposal. You can keep an unfinished sheet.</p>'}</div></div>`:r.view==='compare'?(blocked?'':compare(s,w)):r.view==='learn'?blocked?'':`<section data-sf-computed><h2>Turn a sum into a product</h2>${s.teaching.slice(0,r.step).map((p,i)=>`<p tabindex="-1" data-sf-teaching-step="${i}">${esc(p)}</p>`).join('')}${r.step<s.teaching.length?button('data-sf-step','Read the next step'):model(s.example,s.example)}${button('data-sf-contrasts',r.contrasts?'Hide the contrasts':'Read two contrasts')}${r.contrasts?s.contrasts.map(p=>`<p>${esc(p)}</p>`).join(''):''}</section>`:''}${!blocked&&r.reference?reference(s,w):''}<div class="sf-actions">${button('data-sf-reference','Show a shared-side reference')}${button(`data-sf-keep${ro||blocked?' disabled':''}`,'Keep this sheet')}</div><p>Keep stores a sheet. Changes you have not kept stay only in this visit.</p>`:''}<p id="sf-status" role="status" tabindex="-1">${esc(a?.status??'')}</p><button type="button" data-sf-reopen hidden>Reopen Shared Side</button><footer><a href="#notes">Open Notes</a>${button('data-sf-download','Download Notes')}</footer></section>`;
}
export function bindSharedSide(book,ctx){
 const owner=ctx.explorerId?.(),v=ownerOK(owner)?visit(book,owner,false):null,root=document.querySelector('[data-sf-root]');if(!v?.active||!root)return;v.bound=root;
 const a=current(v),r=a?displayed(a):null,sig=bytes(a?[a.source,r]:null),raw=book.sharedSides,rawPresent=Object.hasOwn(book,'sharedSides'),rawBytes=bytes(raw),screen=v.screen,key=v.key,card=v.card;
 const context=()=>ctx.notebook?.()===book&&ctx.explorerId?.()===owner&&ctx.isActive?.()===true&&location.hash==='#learn/math/equality'&&v.active&&v.bound===root&&root.isConnected&&document.querySelector('[data-sf-root]')===root;
 const fresh=()=>context()&&v.screen===screen&&v.key===key&&v.card===card&&current(v)===a&&bytes(a?[a.source,displayed(a)]:null)===sig&&book.sharedSides===raw&&Object.hasOwn(book,'sharedSides')===rawPresent&&bytes(raw)===rawBytes;
 const tell=t=>{const n=root.querySelector('#sf-status');if(n){n.textContent=t;n.focus();}};
 const live=n=>{if(!context()||!visible(n)||n.disabled)return false;if(fresh())return true;tell('This view has changed. Use Reopen Shared Side to continue.');root.querySelector('[data-sf-reopen]').hidden=false;return false;};
 const redraw=(selector='#sf-heading')=>{stopSpeech();ctx.render?.();const n=document.querySelector(selector);if(n&&!n.disabled)n.focus();else document.querySelector('#sf-heading')?.focus();};
 const request=(next,target=a,focusSelector='#sf-heading')=>{if(!target)return;const result=qualify(book,target,next,ctx);if(!result.ok){target.pending=clone(next);target.status=refused;redraw();return;}adopt(target,next);target.status='';if(result.changed)ctx.save?.();redraw(focusSelector);};
 const on=(q,fn)=>root.querySelectorAll(q).forEach(n=>n.addEventListener('click',()=>{if(live(n))fn(n);}));
 const select=(q,fn)=>root.querySelectorAll(q).forEach(n=>n.addEventListener('change',()=>{if(live(n))fn(n);}));
 const next=()=>clone(displayed(a));
 on('[data-sf-view]',n=>{const name=n.dataset.sfView;if(!['build','compare','learn','shelf'].includes(name))return;if(name==='shelf'){v.screen='shelf';redraw();return;}if(!a){v.screen='draft';if(!current(v))add(v,makeSharedSource(sharedCases[0].id));const d=current(v),q=clone(displayed(d));q.view=name;if(name==='learn')q.work.teachingShown=true;request(q,d);return;}const q=next();q.view=name;if(name==='learn')q.work.teachingShown=true;request(q);});
 on('[data-sf-back]',()=>{v.observer?.disconnect();v.active=false;redraw('[data-equality-shared-side]');});
 select('[data-sf-case]',n=>{if(!sharedCases.some(c=>c.id===n.value))return;let id=v.byCase.get(n.value);if(!id||!v.drafts.has(id)){add(v,makeSharedSource(n.value));id=v.key;v.byCase.set(n.value,id);}v.key=id;v.screen='draft';v.card=null;redraw();});
 select('[data-sf-draft]',n=>{if(v.drafts.has(n.value)){v.key=n.value;v.screen='draft';v.card=null;redraw();}});
 on('[data-sf-choose],[data-sf-clear],[data-sf-adjust]',n=>{if(screen!=='draft'||!a)return;const q=next(),k=n.dataset.sfChoose??n.dataset.sfClear??n.dataset.sfAdjust;if(!['k','a','b'].includes(k))return;if(n.hasAttribute('data-sf-choose'))q.work[k]=q.work[k]===null?1:q.work[k];else if(n.hasAttribute('data-sf-clear'))q.work[k]=null;else{if(q.work[k]===null)return;const value=q.work[k]+Number(n.dataset.sfDelta);if(!Number.isSafeInteger(value)||value<(k==='k'?1:0)||value>24)return;q.work[k]=value;}const attr=n.hasAttribute('data-sf-choose')?'choose':n.hasAttribute('data-sf-clear')?'clear':'adjust';request(q,a,`[data-sf-${attr}="${k}"]${attr==='adjust'?`[data-sf-delta="${n.dataset.sfDelta}"]`:''}`);});
 select('[data-sf-x]',n=>{if(screen!=='draft'||!a)return;const q=next();q.work.x=Number(n.value);if(Number.isInteger(q.work.x)&&q.work.x>=1&&q.work.x<=12)request(q,a,'[data-sf-x]');});
 on('[data-sf-x-one]',()=>{if(screen!=='draft'||!a)return;const q=next();q.work.x=1;request(q,a,'[data-sf-x-one]');});
 on('[data-sf-step]',()=>{if(!a)return;const q=next();q.step=Math.min(a.source.teaching.length,q.step+1);q.work.teachingShown=true;request(q,a,q.step<a.source.teaching.length?'[data-sf-step]':`[data-sf-teaching-step="${q.step-1}"]`);});
 on('[data-sf-contrasts]',()=>{if(!a)return;const q=next();q.contrasts=!q.contrasts;if(q.contrasts)q.work.teachingShown=true;request(q,a,'[data-sf-contrasts]');});
 on('[data-sf-reference]',()=>{if(!a)return;const q=next();q.reference=true;q.work.referenceShown=true;request(q,a,'[data-sf-reference]');});
 on('[data-sf-retry]',()=>{if(a?.pending)request(clone(a.pending));});
 on('[data-sf-keep]',()=>{if(screen!=='draft'||!a||a.pending)return;const id=keepSharedSheet(book,a.source,a.work,{canExport:ctx.canExport});if(!id){a.status='This sheet could not be kept. Your proposal is still here. Download Notes before making space or trying another notebook.';redraw();return;}let saved;try{saved=ctx.save?.();}catch{}a.status=saved?.enabled===true&&saved?.ok===true?'Sheet saved. You can reopen it or copy it to try another proposal.':saved?.enabled===false?'Sheet kept for this session. Saving is off; download Notes to bring it back later.':'Sheet kept in this open notebook, but saving could not be confirmed. Download Notes before closing it.';redraw();document.querySelector('#sf-status')?.focus();});
 on('[data-sf-sheet]',n=>{v.card=n.dataset.sfSheet;v.screen='sheet';syncSheet(book,v);redraw();});
 on('[data-sf-copy]',()=>{if(screen!=='sheet'||!a)return;add(v,a.source,a.work);redraw();});
 on('[data-sf-page]',n=>{v.page=Math.max(0,v.page+Number(n.dataset.sfPage));redraw();});
 on('[data-sf-download]',()=>ctx.downloadNotes?.());
 root.querySelector('[data-sf-reopen]')?.addEventListener('click',n=>{if(context()&&visible(n.currentTarget))redraw();});
 v.observer?.disconnect();
 let observer;const measure=()=>{if(!context()){observer?.disconnect();return;}root.querySelectorAll('[data-sf-rectangle]').forEach(svg=>{const regions=[...svg.querySelectorAll('.sf-x-region,.sf-number-region')],thin=regions.some(n=>{const b=n.getBoundingClientRect();return b.width<12||b.height<12;});const note=svg.parentElement.querySelector('[data-sf-thin]');if(note)note.hidden=!thin;});};
 measure();observer=new ResizeObserver(measure);v.observer=observer;root.querySelectorAll('[data-sf-rectangle]').forEach(svg=>observer.observe(svg));
}
